test('frame: ball should bounce off the top of a brick', () => {
  const state = createState(1);
  // Position ball so it's colliding with the first brick (top-left)
  // First brick: x = offsetX, y = BRICK_TOP
  const firstBrick = state.bricks[0];
  state.ball = {
    x: firstBrick.x + firstBrick.w / 2,
    y: firstBrick.y - BALL_R - 1, // almost touching the top
    r: BALL_R,
    vx: 0,
    vy: 100, // moving down
  };

  const mockCtx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  // Manually advance the ball so it's definitely colliding
  state.ball.y += 2; 

  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, 'ball should be moving up after bouncing off the top of a brick');
  assert.equal(firstBrick.alive, false, 'brick should be destroyed');
});
